@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=438  cases=12
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, tuning.stepToMidi, cm:set, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:setProjectTracks, reaper:addItem, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-80
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 92-101

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 105-113
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 116-125
  @case 'focusState before any render returns both bits false'  [harness]  @ 128-135
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 141-154
  @case 'newTakeBelow + duplicateUnpooledBelow mint a parked slot on scratch and select it'  [harness]  @ 158-179
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 183-206
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 212-267
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 275-304
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 310-353
  @case 'empty grid shows the single no-takes message'  [harness]  @ 359-373
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 380-412
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 416-436

